import java.util.Arrays;
import java.util.Scanner;

public class ArrayCostAnalyzer {
    static int[] findWithChecks(int[] values, int size, int target) {
        for (int i = 0; i < size; i++) {
            if (values[i] == target) {
                return new int[]{i, i + 1};
            }
        }
        return new int[]{-1, size};
    }

    static int insertAt(int[] values, int size, int index, int value) {
        if (size == values.length || index < 0 || index > size) {
            return -1;
        }
        int shifts = 0;
        for (int i = size; i > index; i--) {
            values[i] = values[i - 1];
            shifts++;
        }
        values[index] = value;
        return shifts;
    }

    static int deleteAt(int[] values, int size, int index) {
        if (index < 0 || index >= size) {
            return -1;
        }
        int shifts = 0;
        for (int i = index; i < size - 1; i++) {
            values[i] = values[i + 1];
            shifts++;
        }
        values[size - 1] = 0;
        return shifts;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int capacity = Math.max(0, sc.nextInt());
        int requestedSize = Math.max(0, sc.nextInt());
        int size = Math.min(requestedSize, capacity);
        int[] values = new int[capacity];
        for (int i = 0; i < size; i++) {
            values[i] = sc.nextInt();
        }
        int target = sc.nextInt();
        int insertIndex = sc.nextInt();
        int insertValue = sc.nextInt();
        int deleteIndex = sc.nextInt();

        int[] found = findWithChecks(values, size, target);
        int insertShifts = insertAt(values, size, insertIndex, insertValue);
        if (insertShifts >= 0) {
            size++;
        }
        int deleteShifts = deleteAt(values, size, deleteIndex);
        if (deleteShifts >= 0) {
            size--;
        }

        System.out.println("Found index: " + found[0]);
        System.out.println("Search checks: " + found[1]);
        System.out.println("Insert shifts: " + insertShifts);
        System.out.println("Delete shifts: " + deleteShifts);
        System.out.println("Values: " + Arrays.toString(Arrays.copyOf(values, size)));
    }
}
